/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/packages/ui/src/lib/utils.ts; derived here under Apache-2.0.
 */
export { cn } from "cn";

/**
 * Original design by Gustavo Fior (@gustavo-fior) and Foglamp Labs,
 * co-founded by Abdul Haidar. Extracted AS-IS from foglamp-labs/foglamp.
 */

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { type VariantProps, cva } from "class-variance-authority";
import * as React from "react";

import { cn } from "../lib/utils";

const badgeVariants = cva(
	"group/badge inline-flex w-fit rounded-full shrink-0 items-center justify-center capitalize overflow-hidden font-medium whitespace-nowrap transition-all focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 [&>svg]:pointer-events-none [&_svg]:shrink-0",
	{
		variants: {
			variant: {
				default:
					"bg-primary text-primary-foreground shadow-[var(--custom-shadow-primary)] [a]:hover:bg-primary/80",
				secondary:
					"bg-secondary shadow-(--custom-shadow-secondary) text-secondary-foreground [a]:hover:bg-secondary/80",
				destructive:
					"bg-destructive/10 text-destructive shadow-(--custom-shadow-destructive) focus-visible:ring-destructive/20 dark:bg-destructive/20 dark:focus-visible:ring-destructive/40 [a]:hover:bg-destructive/20",
				green:
					"bg-green-500/10 text-green-700 shadow-[var(--custom-shadow-green)] focus-visible:ring-green-500/20 dark:bg-green-500/15 dark:text-green-300 dark:focus-visible:ring-green-500/40 [a]:hover:bg-green-500/20",
				blue: "bg-blue-500/10 text-blue-700 shadow-[var(--custom-shadow-blue)] focus-visible:ring-blue-500/20 dark:bg-blue-500/15 dark:text-blue-300 dark:focus-visible:ring-blue-500/40 [a]:hover:bg-blue-500/20",
				amber:
					"bg-amber-500/10 text-amber-700 shadow-[var(--custom-shadow-amber)] focus-visible:ring-amber-500/20 dark:bg-amber-500/15 dark:text-amber-300 dark:focus-visible:ring-amber-500/40 [a]:hover:bg-amber-500/20",
				orange:
					"bg-orange-500/10 text-orange-600 shadow-[var(--custom-shadow-orange)] focus-visible:ring-orange-500/20 dark:bg-orange-600/15 dark:text-orange-400 dark:focus-visible:ring-orange-500/40 [a]:hover:bg-orange-500/20",
				emerald:
					"bg-emerald-500/10 text-emerald-700 shadow-[var(--custom-shadow-emerald)] focus-visible:ring-emerald-500/20 dark:bg-emerald-500/15 dark:text-emerald-300 dark:focus-visible:ring-emerald-500/40 [a]:hover:bg-emerald-500/20",
				rose: "bg-rose-500/10 text-rose-700 shadow-[var(--custom-shadow-rose)] focus-visible:ring-rose-500/20 dark:bg-rose-500/15 dark:text-rose-400 dark:focus-visible:ring-rose-500/40 [a]:hover:bg-rose-500/20",
				red: "bg-red-500/10 text-red-700 shadow-[var(--custom-shadow-red)] focus-visible:ring-red-500/20 dark:bg-red-500/15 dark:text-red-400 dark:focus-visible:ring-red-500/40 [a]:hover:bg-red-500/20",
				violet:
					"bg-violet-500/10 text-violet-700 shadow-[var(--custom-shadow-violet)] focus-visible:ring-violet-500/20 dark:bg-violet-500/15 dark:text-violet-300 dark:focus-visible:ring-violet-500/40 [a]:hover:bg-violet-500/20",
				fuchsia:
					"bg-fuchsia-500/10 text-fuchsia-700 shadow-[var(--custom-shadow-fuchsia)] focus-visible:ring-fuchsia-500/20 dark:bg-fuchsia-500/15 dark:text-fuchsia-300 dark:focus-visible:ring-fuchsia-500/40 [a]:hover:bg-fuchsia-500/20",
				sky: "bg-sky-500/10 text-sky-700 shadow-[var(--custom-shadow-sky)] focus-visible:ring-sky-500/20 dark:bg-sky-500/15 dark:text-sky-300 dark:focus-visible:ring-sky-500/40 [a]:hover:bg-sky-500/20",
				outline:
					"shadow-(--custom-shadow) text-foreground [a]:hover:bg-muted [a]:hover:text-muted-foreground",
			},
			size: {
				sm: "h-4 px-1.5 gap-1 text-[10px] has-[>svg:first-child]:pl-1 has-[>svg:last-child]:pr-1 [&_svg:not([class*='size-'])]:size-2.5!",
				md: "h-5 px-2 gap-[5px] text-xs has-[>svg:first-child]:pl-1.5 has-[>svg:last-child]:pr-1.5 [&_svg:not([class*='size-'])]:size-3!",
				lg: "h-6 px-2.5 gap-1.5 text-sm has-[>svg:first-child]:pl-2 has-[>svg:last-child]:pr-2 [&_svg:not([class*='size-'])]:size-3.5!",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "md",
		},
	},
);

function Badge({
	className,
	variant = "default",
	size = "md",
	render,
	children,
	...props
}: useRender.ComponentProps<"span"> & VariantProps<typeof badgeVariants>) {
	const wrappedChildren = React.Children.map(children, (child) =>
		typeof child === "string" || typeof child === "number" ? (
			<span>{child}</span>
		) : (
			child
		),
	);

	return useRender({
		defaultTagName: "span",
		props: mergeProps<"span">(
			{
				className: cn(badgeVariants({ variant, size }), className),
				children: wrappedChildren,
			},
			props,
		),
		render,
		state: {
			slot: "badge",
			variant,
			size,
		},
	});
}

export { Badge, badgeVariants };

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/components/app/span-type.tsx; derived here under Apache-2.0.
 */
import { Badge } from "../../ui/badge";
import { cn } from "../../lib/utils";
import {
  type Icon,
  IconCircleDashed,
  IconGhost,
  IconSparkles,
  IconTool,
  IconVector,
} from "@tabler/icons-react";

type BadgeVariant = "violet" | "blue" | "amber" | "emerald" | "secondary";

// Badge color per span type. Shared so the type badge, its waterfall bar, and
// any other surface read as one consistent palette.
export const SPAN_TYPE_VARIANT: Record<string, BadgeVariant> = {
  llm: "violet",
  tool: "blue",
  agent: "amber",
  embedding: "emerald",
  other: "secondary",
};

// Icon per span type: a model (llm), a wrench (tool), a ghost (agent), a vector
// (embedding), falling back to a dashed circle for anything else.
export const SPAN_TYPE_ICON: Record<string, Icon> = {
  llm: IconSparkles,
  tool: IconTool,
  agent: IconGhost,
  embedding: IconVector,
  other: IconCircleDashed,
};

// Waterfall bar fill per span type — mirrors the badge color so a row's label
// and its bar read as one.
export const SPAN_TYPE_BAR: Record<string, string> = {
  llm: "bg-violet-500",
  tool: "bg-blue-500",
  agent: "bg-amber-500",
  embedding: "bg-emerald-500",
  other: "bg-slate-500",
};

export function spanTypeIcon(type: string): Icon {
  return SPAN_TYPE_ICON[type] ?? IconCircleDashed;
}

export function spanTypeVariant(type: string): BadgeVariant {
  return SPAN_TYPE_VARIANT[type] ?? "secondary";
}

export function spanTypeBar(type: string): string {
  return SPAN_TYPE_BAR[type] ?? "bg-primary/70";
}

// Icon-chip palette per span type — a tinted fill + matching foreground, for the
// compact icon-only chip used where a full text badge would be too wide (e.g.
// the waterfall's label gutter). Light mode gets an accent-tinted inset ring +
// drop shadow (same recipe as nav.ts) — --custom-shadow washes out on light.
export const SPAN_TYPE_CHIP: Record<string, string> = {
  llm: "bg-violet-500/15 text-violet-600 dark:text-violet-400 shadow-[inset_0_0_0_1px_rgba(139,92,246,0.14),0_2px_6px_-2px_rgba(139,92,246,0.25)] dark:shadow-(--custom-shadow)",
  tool: "bg-blue-500/15 text-blue-600 dark:text-blue-400 shadow-[inset_0_0_0_1px_rgba(59,130,246,0.14),0_2px_6px_-2px_rgba(59,130,246,0.25)] dark:shadow-(--custom-shadow)",
  agent:
    "bg-amber-500/15 text-amber-600 dark:text-amber-400 shadow-[inset_0_0_0_1px_rgba(245,158,11,0.14),0_2px_6px_-2px_rgba(245,158,11,0.25)] dark:shadow-(--custom-shadow)",
  embedding:
    "bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 shadow-[inset_0_0_0_1px_rgba(16,185,129,0.14),0_2px_6px_-2px_rgba(16,185,129,0.25)] dark:shadow-(--custom-shadow)",
  other:
    "bg-slate-500/15 text-slate-600 dark:text-slate-400 shadow-[inset_0_0_0_1px_rgba(100,116,139,0.14),0_2px_6px_-2px_rgba(100,116,139,0.25)] dark:shadow-(--custom-shadow)",
};

export function spanTypeChip(type: string): string {
  return (
    SPAN_TYPE_CHIP[type] ??
    "bg-primary/15 text-primary shadow-[inset_0_0_0_1px_rgba(100,116,139,0.14),0_2px_6px_-2px_rgba(100,116,139,0.25)] dark:shadow-(--custom-shadow)"
  );
}

/** A compact, icon-only span-type chip — the type's color + icon in a small
 * rounded square, with the type name as a tooltip. Used where horizontal space
 * is tight (the waterfall rows) and the full {@link SpanTypeBadge} is too wide. */
export function SpanTypeChip({
  type,
  className,
}: {
  type: string;
  className?: string;
}) {
  const Icon = spanTypeIcon(type);
  return (
    <span
      title={type}
      className={cn(
        "flex size-4.5 shrink-0 items-center justify-center rounded-md corner-squircle",
        spanTypeChip(type),
        className
      )}
    >
      {/* Tabler ships no IconToolFilled; filling the outline's closed path
          gets the solid look the other chip icons have. */}
      <Icon className={cn("size-3", type === "tool" && "fill-current")} />
    </span>
  );
}

/** A span-type pill — the type's color + icon + label, used everywhere a span's
 * kind is shown (waterfall labels, the inspector, the scores panel). */
export function SpanTypeBadge({
  type,
  className,
}: {
  type: string;
  className?: string;
}) {
  const Icon = spanTypeIcon(type);
  return (
    <Badge variant={spanTypeVariant(type)} className={cn(className)}>
      <Icon />
      {type}
    </Badge>
  );
}
